import React, { useState, useCallback } from 'react';
import { BIBLE_VERSES } from '../constants';

const VerseOfTheDay: React.FC = () => {
  const [currentVerse, setCurrentVerse] = useState<{ text: string; reference: string } | null>(null);

  const getRandomVerse = useCallback(() => {
    const randomIndex = Math.floor(Math.random() * BIBLE_VERSES.length);
    setCurrentVerse(BIBLE_VERSES[randomIndex]);
  }, []);

  return (
    <div className="bg-white p-6 md:p-8 rounded-lg shadow-lg text-center max-w-lg mx-auto border-t-4 border-emerald-500">
      <h3 className="text-xl md:text-2xl font-semibold text-emerald-800 mb-4">Wersety Nadziei</h3>
      {currentVerse ? (
        <div className="mb-6">
          <p className="italic text-lg md:text-xl text-stone-700 leading-relaxed">
            &bdquo;{currentVerse.text}&rdquo;
          </p>
          <p className="mt-3 text-emerald-600 font-medium">
            &ndash; {currentVerse.reference}
          </p>
        </div>
      ) : (
        <p className="text-stone-600 text-base md:text-lg mb-6">
          Kliknij poniżej, aby otrzymać słowo nadziei i inspiracji na dziś.
        </p>
      )}
      <button
        onClick={getRandomVerse}
        className="bg-emerald-600 hover:bg-emerald-700 text-white font-bold py-3 px-6 rounded-full transition duration-300 ease-in-out transform hover:scale-105 shadow-md"
      >
        Odkryj Słowo Dnia
