import React, { useState, useEffect, useRef, useCallback } from 'react';
import Header from './components/Header';
import Footer from './components/Footer';
import VerseOfTheDay from './components/VerseOfTheDay';
import ContactCard from './components/ContactCard';
import HeroSection from './components/HeroSection';

const DEFAULT_AVATAR_SVG = `data:image/svg+xml;base64,`;

const App: React.FC = () => {
  const [showWelcome, setShowWelcome] = useState(true);
  const [profileImageFile, setProfileImageFile] = useState<File | null>(null);
  const [profileImageUrl, setProfileImageUrl] = useState<string>(DEFAULT_AVATAR_SVG);

  const fileInputRef = useRef<HTMLInputElement>(null); // Ref do inputa pliku

  // Obsługa zmiany pliku
  const handleFileChange = useCallback((event: React.ChangeEvent<HTMLInputElement>) => {
    if (event.target.files && event.target.files.length > 0) {
      const file = event.target.files[0];
      setProfileImageFile(file);

      // Jeśli poprzedni URL był obiektowym URL, zwolnij go
      if (profileImageUrl.startsWith('blob:')) {
        URL.revokeObjectURL(profileImageUrl);
      }
      setProfileImageUrl(URL.createObjectURL(file));
    }
  }, [profileImageUrl]);

  // Obsługa usunięcia zdjęcia
  const handleRemoveImage = useCallback(() => {
    if (profileImageUrl.startsWith('blob:')) {
      URL.revokeObjectURL(profileImageUrl);
    }
    setProfileImageFile(null);
    setProfileImageUrl(DEFAULT_AVATAR_SVG);
    if (fileInputRef.current) {
      fileInputRef.current.value = ''; // Resetuj input pliku
    }
  }, [profileImageUrl]);

  // Efekt do czyszczenia obiektowych URL-i
  useEffect(() => {
    // Cleanup function - wywoływana przy odmontowaniu lub zmianie zależności
    return () => {
      if (profileImageUrl.startsWith('blob:')) {
        URL.revokeObjectURL(profileImageUrl);
      }
    };
  }, [profileImageUrl]); // Re-run effect if profileImageUrl changes

  useEffect(() => {
    const timer = setTimeout(() => {
      setShowWelcome(false);
    }, 2500);

    return () => clearTimeout(timer);
  }, []);

  return (
    <div className="min-h-screen flex flex-col font-sans bg-blue-50 text-stone-800 selection:bg-blue-200">
      {showWelcome && (
        <div className="fixed inset-0 bg-blue-900 flex items-center justify-center z-[100] transition-opacity duration-1000">
          <div className="text-center px-6 animate-fadeIn">
             <div className="w-20 h-1.5 bg-blue-400 mx-auto mb-8 rounded-full"></div>
            <p className="text-blue-50 text-4xl md:text-6xl font-bold mb-4 tracking-tight">
              Dobrze, że jesteś.
            </p>
            <p className="text-blue-300 text-xl md:text-2xl font-medium max-w-md mx-auto">
              Zrób pierwszy krok ku wolności razem z nami.
            </p>
          </div>
        </div>
      )}

      <Header />

      <main className="flex-grow">
        <div className="container mx-auto px-4 py-12 lg:py-20">
          {/* Sekcja do wgrywania zdjęcia profilowego */}
          <section className="mb-12 p-6 bg-white rounded-2xl shadow-md border border-blue-100 max-w-xl mx-auto text-center">
            <h3 className="block text-xl font-bold text-blue-900 mb-4">
              Twoje zdjęcie profilowe
            </h3>
            <div className="flex flex-col items-center gap-4">
              <div className="relative w-24 h-24 rounded-full border-4 border-blue-200 bg-gray-100 flex items-center justify-center overflow-hidden">
                <img
                  src={profileImageUrl}
                  alt="Podgląd zdjęcia profilowego"
                  className="w-full h-full object-cover"
                />
              </div>
              <input
                id="profileImageInput"
                type="file"
                accept="image/*"
                onChange={handleFileChange}
                className="block w-full text-sm text-stone-500
                         file:mr-4 file:py-2 file:px-4
                         file:rounded-full file:border-0
                         file:text-sm file:font-semibold
                         file:bg-blue-100 file:text-blue-700
                         hover:file:bg-blue-200 cursor-pointer"
                ref={fileInputRef}
                aria-label="Wybierz plik zdjęcia profilowego"
              />
              {profileImageFile && (
                <button
                  onClick={handleRemoveImage}
                  className="mt-2 text-red-600 hover:text-red-800 text-sm font-medium"
                >
                  Usuń zdjęcie
                </button>
              )}
            </div>
            <p className="text-sm text-stone-500 mt-4">
              Wgraj zdjęcie, aby spersonalizować swój profil.
            </p>
          </section>

          <section id="hero" className="mb-32">
            <HeroSection profileImageUrl={profileImageUrl} />
          </section>

          <section id="verse" className="mb-32">
            <div className="relative">
              <div className="absolute inset-0 bg-blue-600/5 blur-3xl rounded-full"></div>
              <div className="relative">
                <VerseOfTheDay />
              </div>
            </div>
          </section>

          <section id="contact" className="mb-20">
            <ContactCard />
          </section>
        </div>
      </main>

      <Footer />
    </div>
  );
};

