const DEFAULT_AVATAR_SVG = `data:image/svg+xml;base64,`;

const HeroSection: React.FC = () => {
  // Usunięto state profileImageFile, ponieważ nie jest potrzebny do warunkowego renderowania przycisku usuwania.
  const [profileImageUrl, setProfileImageUrl] = useState<string>(DEFAULT_AVATAR_SVG);

  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = useCallback((event: React.ChangeEvent<HTMLInputElement>) => {
    if (event.target.files && event.target.files.length > 0) {
      const file = event.target.files[0];
      // Nie ustawiamy profileImageFile, bo już go nie potrzebujemy.

      // Jeśli poprzedni URL był obiektowym URL, zwolnij go
      if (profileImageUrl.startsWith('blob:')) {
        URL.revokeObjectURL(profileImageUrl);
      }
      setProfileImageUrl(URL.createObjectURL(file));
    }
  }, [profileImageUrl]);

  // Usunięto funkcję handleRemoveImage

  useEffect(() => {
    return () => {
      // Nadal czyścimy obiektowy URL, jeśli jest aktywny, przy odmontowaniu komponentu
