import React, { useState, useEffect } from 'react';

interface TypewriterProps {
  text: string;
  delay?: number; // Opóźnienie między znakami
  cursorInterval?: number; // Interwał mrugania kursora
  className?: string; // Klasy CSS dla całego komponentu tekstowego
  cursorClassName?: string; // Klasy CSS dla samego kursora
  highlightWord?: string; // Słowo do podświetlenia
  highlightClassName?: string; // Klasy CSS dla podświetlonego słowa
}

const Typewriter: React.FC<TypewriterProps> = ({
  text,
  delay = 70, // Domyślne opóźnienie między znakami
  cursorInterval = 500, // Domyślny interwał mrugania kursora
  className = '',
  cursorClassName = 'border-r-2 border-current animate-blink-cursor inline-block w-[0.1em] ml-1', // Tailwind classes for cursor
  highlightWord,
  highlightClassName,
}) => {
  const [currentText, setCurrentText] = useState('');
  const [currentIndex, setCurrentIndex] = useState(0);
  const [showCursor, setShowCursor] = useState(true);

  // Efekt pisania
  useEffect(() => {
    if (currentIndex < text.length) {
      const timeout = setTimeout(() => {
        setCurrentText(prevText => prevText + text[currentIndex]);
        setCurrentIndex(prevIndex => prevIndex + 1);
      }, delay);
      return () => clearTimeout(timeout);
    }
  }, [currentIndex, delay, text]);

  // Efekt mrugania kursora
  useEffect(() => {
    const cursorTimeout = setInterval(() => {
      setShowCursor(prev => !prev);
    }, cursorInterval);
    return () => clearInterval(cursorTimeout);
  }, [cursorInterval]);

  // Funkcja renderująca tekst z opcjonalnym podświetleniem
  const renderTextWithHighlight = (fullTypedText: string) => {
    if (!highlightWord || !highlightClassName) {
      return fullTypedText;
    }

    const regex = new RegExp(`(${highlightWord})`, 'gi');
    const parts = fullTypedText.split(regex);

    return parts.map((part, index) => {
      if (part.toLowerCase() === highlightWord.toLowerCase()) {
        return (
          <span key={index} className={highlightClassName}>
            {part}
          </span>
        );
      }
      return part;
    });
  };

  return (
    <span className={className}>
      {renderTextWithHighlight(currentText)}
      {/* Kursor wyświetla się tylko po zakończeniu pisania */}
      {currentIndex === text.length && (
        <span className={`${showCursor ? 'opacity-100' : 'opacity-0'} ${cursorClassName}`}>&nbsp;</span>
      )}
    </span>
  );
};

export default Typewriter;

